function serviceById(id){return pricesData.services.find(s=>s.id===id)}
function serviceTitle(id,lang=currentLang()){const s=serviceById(id); return s?.[lang]?.title || s?.de?.title || id}
function money(n){return Number.isInteger(Number(n))?String(Number(n)):Number(n).toFixed(2).replace('.',',')}
function renderPrices(){
 const lang=currentLang(), fit=document.getElementById('fitnessPriceGrid'), massage=document.getElementById('massagePriceGrid');
 if(fit){
   const fitness=pricesData.services.filter(s=>s.visible!==false&&s.category==='fitness'&&s.showInPriceList!==false).sort((a,b)=>(a.order||0)-(b.order||0));
   fit.innerHTML=fitness.flatMap(s=>{
     if(s.pricingType==='packages') return s.prices.map(p=>`<article class="price-card ${p.quantity===12?'featured':''}">${p.quantity===12?'<span>★</span>':''}<h3>${p.quantity} ${lang==='de'?'Einheiten':lang==='en'?'classes':lang==='uk'?'занять':'занятий'}</h3><strong>${money(p.totalPrice)} €</strong><small>${money(p.unitPrice)} € / ${lang==='de'?'Einheit':lang==='en'?'class':lang==='uk'?'заняття':'занятие'}</small></article>`);
     const p=s.prices[0]; return p?[`<article class="price-card"><h3>${s[lang]?.title||s.de.title}</h3><strong>${money(p.totalPrice)} €</strong></article>`]:[];
   }).join('');
 }
 if(massage){
  const items=pricesData.services.filter(s=>s.visible!==false&&s.category==='massage'&&s.showInPriceList!==false).sort((a,b)=>(a.order||0)-(b.order||0));
  massage.innerHTML=items.map(s=>`<div><span>${s[lang]?.title||s.de.title}</span><b>${money(s.prices?.[0]?.totalPrice||0)} €</b></div>`).join('');
 }
}
function initBlogCarousel(){
 const carousel=document.querySelector('[data-blog-carousel]'); if(!carousel)return;
 const track=carousel.querySelector('.blog-grid'), cards=Array.from(track.querySelectorAll('.blog-card')), prev=carousel.querySelector('.blog-prev'), next=carousel.querySelector('.blog-next'), counter=carousel.querySelector('.blog-counter');
 if(!cards.length){if(counter)counter.textContent='0 / 0';return;} let index=0;
 const update=()=>counter&&(counter.textContent=`${index+1} / ${cards.length}`);
 const go=n=>{index=(n+cards.length)%cards.length;cards[index].scrollIntoView({behavior:'smooth',block:'nearest',inline:'start'});update()};
 if(prev)prev.onclick=()=>go(index-1); if(next)next.onclick=()=>go(index+1); update();
}
function renderBlog(){
 const lang=currentLang(), grid=document.getElementById('blogGrid'); if(!grid)return;
 const arts=blogData.articles.filter(a=>a.visible!==false).sort((a,b)=>(a.order||a.id)-(b.order||b.id));
 grid.innerHTML=arts.map(a=>{const x=a[lang]||a.de;return `<article class="blog-card"><img src="${a.image}" alt="${x.title.replace(/"/g,'&quot;')}" loading="lazy"><div><h3>${x.title}</h3><p>${x.excerpt||''}</p><button class="btn outline blog-open" data-article="${a.id}">${translations[lang].readMore}</button></div></article>`}).join('');
 document.querySelectorAll('.blog-open').forEach(b=>b.onclick=()=>openArticle(Number(b.dataset.article))); initBlogCarousel();
}
const modal=document.getElementById('articleModal');
function openArticle(id){const a=blogData.articles.find(x=>Number(x.id)===Number(id)); if(!a)return; const x=a[currentLang()]||a.de; document.getElementById('articleModalTitle').textContent=x.title;document.getElementById('articleModalBody').innerHTML=x.content||'';modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
const closeArticle=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true')};
document.querySelector('.article-close')?.addEventListener('click',closeArticle); modal?.addEventListener('click',e=>{if(e.target===modal)closeArticle()});
function isoLocal(d){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function applicableRegular(date){
 const iso=isoLocal(date), weekday=date.getDay()===0?7:date.getDay();
 return regularData.regularEvents.filter(e=>e.visible!==false&&e.weekday===weekday&&(!e.startDate||iso>=e.startDate)&&(!e.endDate||iso<=e.endDate));
}
function eventsForDate(date){
 const iso=isoLocal(date); let events=applicableRegular(date).map(e=>({id:e.id,regularEventId:e.id,serviceId:e.serviceId,time:e.time,duration:e.duration,source:'regular'}));
 const ex=exceptionsData.exceptions.filter(x=>x.date===iso&&x.visible!==false);
 const excluded=new Set(ex.filter(x=>x.type==='exclude').map(x=>x.regularEventId)); events=events.filter(e=>!excluded.has(e.regularEventId));
 ex.filter(x=>x.type==='add').forEach(x=>events.push({id:x.id,serviceId:x.serviceId,time:x.time||'',duration:x.duration,source:'exception'}));
 return events.sort((a,b)=>(a.time||'99:99').localeCompare(b.time||'99:99'));
}
function renderCalendar(){
 const desktop=document.getElementById('calendarDesktop'), mobile=document.getElementById('calendarMobile'); if(!desktop||!mobile)return;
 const lang=currentLang(), locale=lang==='uk'?'uk-UA':lang==='en'?'en-GB':lang==='ru'?'ru-RU':'de-DE'; const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 document.getElementById('calendarTitle').textContent=new Intl.DateTimeFormat(locale,{month:'long',year:'numeric'}).format(calendarDate);
 const labels={de:['Mo','Di','Mi','Do','Fr','Sa','So'],uk:['Пн','Вт','Ср','Чт','Пт','Сб','Нд'],ru:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],en:['Mon','Tue','Wed','Thu','Fri','Sat','Sun']}; desktop.innerHTML=labels[lang].map(d=>`<div class="cal-head">${d}</div>`).join(''); mobile.innerHTML='';
 let first=(new Date(y,m,1).getDay()+6)%7; for(let i=0;i<first;i++)desktop.innerHTML+='<div class="cal-day empty"></div>'; const count=new Date(y,m+1,0).getDate(), groups=[];
 for(let d=1;d<=count;d++){const date=new Date(y,m,d),evs=eventsForDate(date),past=date<today,isToday=date.toDateString()===now.toDateString();desktop.innerHTML+=`<div class="cal-day ${isToday?'today':''} ${past?'past':''}"><div class="cal-num">${d}</div>${evs.map(e=>`<button class="cal-event" data-service="${e.serviceId}" data-date="${isoLocal(date)}">${e.time?e.time+' · ':''}${serviceTitle(e.serviceId,lang)} · ${translations[lang].from10}</button>`).join('')}</div>`;if(evs.length&&!past)groups.push({date,evs});}
 if(!groups.length)mobile.innerHTML=`<p class="calendar-empty">${translations[lang].noUpcomingClasses}</p>`; else {const lim=8;mobile.innerHTML=groups.map((g,i)=>`<div class="mobile-day${i>=lim?' mobile-day-extra':''}"><div class="mobile-date">${new Intl.DateTimeFormat(locale,{weekday:'short',day:'numeric',month:'short'}).format(g.date)}</div><div class="mobile-events">${g.evs.map(e=>`<button class="cal-event" data-service="${e.serviceId}" data-date="${isoLocal(g.date)}"><span class="event-time">${e.time||'—'}</span><span class="event-name">${serviceTitle(e.serviceId,lang)}</span><span class="event-price">${translations[lang].from10}</span></button>`).join('')}</div></div>`).join('');if(groups.length>lim){mobile.innerHTML+=`<button type="button" class="calendar-more" id="calendarMore">${translations[lang].showMoreClasses}</button>`;document.getElementById('calendarMore').onclick=e=>{mobile.querySelectorAll('.mobile-day-extra').forEach(x=>x.classList.remove('mobile-day-extra'));e.currentTarget.remove()}}}
 document.querySelectorAll('.cal-event').forEach(b=>b.onclick=()=>{const service=pricesData?.services?.find(s=>s.id===b.dataset.service);const type=service?.category==='massage'?'massage':'training';openBookingChoices({serviceId:b.dataset.service,date:b.dataset.date,label:`${serviceTitle(b.dataset.service,lang)} | ${b.dataset.date}`},type);});
}
let bookingContext={label:'',serviceId:'',date:''};
let bookingType='training';
function bookingValues(){
 const option=document.getElementById('bookingOption');
 return {name:document.getElementById('bookingName')?.value.trim()||'',option:option?.selectedOptions?.[0]?.textContent||'',date:document.getElementById('bookingDate')?.value||'',contact:document.getElementById('bookingContact')?.value.trim()||'',message:document.getElementById('bookingMessage')?.value.trim()||''};
}
function bookingText(){const v=bookingValues();return [bookingContext.label,v.option,v.date,v.name,v.contact,v.message].filter(Boolean).join(' | ')}
function openBookingChoices(context={},type='training'){
 bookingContext=typeof context==='string'?{label:context,serviceId:'',date:''}:{label:context?.label||'',serviceId:context?.serviceId||'',date:context?.date||''};
 bookingType=type==='massage'?'massage':'training';
 const m=document.getElementById('bookingChoiceModal');m?.classList.add('open');m?.setAttribute('aria-hidden','false');document.body.classList.add('modal-open');updateBookingLinks();
}
function closeBookingChoices(){const m=document.getElementById('bookingChoiceModal');m?.classList.remove('open');m?.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open')}
function universalTelegramUrl(){return siteConfig?.booking?.telegram||siteConfig?.social?.telegram||''}
function universalWhatsAppUrl(type=bookingType){if(type==='massage')return siteConfig?.booking?.whatsappMassage||'https://wa.me/4915226130049';return siteConfig?.booking?.whatsapp||siteConfig?.social?.whatsapp||''}
function openTelegramBooking(){const url=universalTelegramUrl();if(!url){alert(translations[currentLang()].telegramMissing||'Telegram link is not configured yet.');return;}window.open(url,'_blank','noopener,noreferrer')}
function openWhatsAppBooking(){const url=universalWhatsAppUrl();if(!url)return;const text=bookingContext.label||'';const sep=url.includes('?')?'&':'?';window.open(url+(text?sep+'text='+encodeURIComponent(text):''),'_blank','noopener,noreferrer')}
function visibleMassageServices(){return pricesData.services.filter(s=>s.visible!==false&&s.category==='massage').sort((a,b)=>(a.order||0)-(b.order||0))}
function renderBookingOptions(preferred=''){
 const select=document.getElementById('bookingOption'), dateInput=document.getElementById('bookingDate'), label=document.getElementById('bookingOptionLabel'); if(!select||!dateInput||!label)return;
 const lang=currentLang(), t=translations[lang]; label.textContent=bookingType==='massage'?t.formMassage:t.formTraining;
 if(bookingType==='massage'){
   const items=visibleMassageServices();
   select.disabled=false;
   select.innerHTML=`<option value="">${t.bookingSelectMassage}</option>`+items.map(s=>`<option value="${s.id}">${serviceTitle(s.id,lang)}</option>`).join('');
   if(preferred&&items.some(s=>s.id===preferred))select.value=preferred;
 }else{
   const date=dateInput.value;
   if(!date){select.disabled=true;select.innerHTML=`<option value="">${t.bookingSelectDate}</option>`;validateBookingForm();return;}
   const evs=eventsForDate(new Date(date+'T12:00:00'));
   if(!evs.length){select.disabled=true;select.innerHTML=`<option value="">${t.bookingNoClasses}</option>`;validateBookingForm();return;}
   select.disabled=false;
   select.innerHTML=`<option value="">${t.bookingSelectTraining}</option>`+evs.map((e,i)=>`<option value="${e.serviceId}@@${e.time||''}@@${i}">${e.time?e.time+' — ':''}${serviceTitle(e.serviceId,lang)}</option>`).join('');
   if(preferred){const opt=[...select.options].find(o=>o.value.startsWith(preferred+'@@'));if(opt)select.value=opt.value;}
 }
 validateBookingForm();
}
function renderBookingForm(){
 const form=document.getElementById('bookingForm');if(!form)return;form.dataset.mode=bookingType;
 const dateInput=document.getElementById('bookingDate'); if(dateInput){dateInput.min=isoLocal(new Date()); if(bookingContext.date)dateInput.value=bookingContext.date;}
 renderBookingOptions(bookingContext.serviceId||'');
 validateBookingForm();
}
function validateBookingForm(){
 const name=document.getElementById('bookingName')?.value.trim()||'', date=document.getElementById('bookingDate')?.value||'', option=document.getElementById('bookingOption')?.value||'', contact=document.getElementById('bookingContact')?.value.trim()||'', btn=document.querySelector('.site-booking-submit');
 if(btn)btn.disabled=!(name&&date&&option&&contact);
}
function openSiteBooking(){closeBookingChoices();const form=document.getElementById('bookingForm');if(!form)return;renderBookingForm();form.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>document.getElementById('bookingName')?.focus({preventScroll:true}),550)}
function sendSiteBooking(){if(document.querySelector('.site-booking-submit')?.disabled)return;const email=siteConfig?.booking?.email||'pisarevskaya.ks@gmail.com';const subject={de:'Buchungsanfrage über die Website',uk:'Запит на запис із сайту',ru:'Запрос на запись с сайта',en:'Booking request from website'}[currentLang()];location.href=`mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(bookingText())}`}
function updateBookingLinks(){const tg=document.getElementById('bookTelegram'),wa=document.getElementById('bookWhatsApp');if(tg){const ok=!!universalTelegramUrl();tg.classList.toggle('disabled',!ok);tg.setAttribute('aria-disabled',ok?'false':'true')}if(wa){const ok=!!universalWhatsAppUrl();wa.classList.toggle('disabled',!ok);wa.setAttribute('aria-disabled',ok?'false':'true')}}
document.querySelectorAll('.booking-trigger').forEach(el=>el.addEventListener('click',e=>{e.preventDefault();openBookingChoices({},el.dataset.bookingType==='massage'?'massage':'training')}));
document.querySelector('.booking-choice-close')?.addEventListener('click',closeBookingChoices);
document.getElementById('bookingChoiceModal')?.addEventListener('click',e=>{if(e.target.id==='bookingChoiceModal')closeBookingChoices()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeBookingChoices()});
document.getElementById('bookTelegram')?.addEventListener('click',e=>{e.preventDefault();if(e.currentTarget.getAttribute('aria-disabled')==='true')return;openTelegramBooking()});
document.getElementById('bookWhatsApp')?.addEventListener('click',e=>{e.preventDefault();if(e.currentTarget.getAttribute('aria-disabled')==='true')return;openWhatsAppBooking()});
document.getElementById('bookOnSite')?.addEventListener('click',openSiteBooking);
document.getElementById('bookingDate')?.addEventListener('change',()=>{bookingContext.date='';bookingContext.serviceId='';renderBookingOptions()});
['bookingName','bookingContact','bookingOption'].forEach(id=>document.getElementById(id)?.addEventListener('input',validateBookingForm));
document.getElementById('bookingOption')?.addEventListener('change',validateBookingForm);
document.querySelector('.site-booking-submit')?.addEventListener('click',sendSiteBooking);
const originalSetLang=setLang; setLang=function(lang){originalSetLang(lang);renderPrices();renderBlog();renderCalendar();renderBookingForm()};
async function loadV9(){
 try{[pricesData,blogData,regularData,exceptionsData,siteConfig]=await Promise.all(['content/prices.json','content/blog.json','content/regular_schedule.json','content/schedule_exceptions.json','config/site.json'].map(u=>fetch(u,{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error(u);return r.json()})));}catch(e){console.warn('JSON fetch unavailable; using embedded preview data',e);pricesData=fallbackPrices;blogData=fallbackBlog;regularData=fallbackRegular;exceptionsData=fallbackExceptions;siteConfig={social:{whatsapp:'https://wa.me/4917624785836',telegram:''},booking:{whatsapp:'https://wa.me/4917624785836',whatsappMassage:'https://wa.me/4915226130049',telegram:'',email:'pisarevskaya.ks@gmail.com'}}}
 updateBookingLinks();
 setLang('de');
}
loadV9();
